            "metrics": ["status", "restartCount"],
            "events": [WatchEvent.ADDED, WatchEvent.MODIFIED, WatchEvent.DELETED]
        }
    }

    observers = []

    for resource in app.spec.manifest:
        kind = resource.get("kind")
        if kind and kind not in app.spec.observer_schemas and kind in default_schemas:
            default_schema = default_schemas[kind]
            observer = ObserverSchema(
                resource_ref=ResourceRef(api=resource["apiVersion"], kind=kind, name=resource["metadata"]["name"]),
                metrics=default_schema["metrics"],
                events=default_schema["events"]
            )
            observers.append(observer)

    return observers

