import re

class SQLParams:
    in_style = 'named'  # This can be 'named' or 'ordinal'

    @staticmethod
    def format(
        sql: AnyStr,
        params: Union[Dict[Union[str, int], Any], Sequence[Any]],
    ) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
        if SQLParams.in_style == 'named':
            out_params = {f':{key}': value for key, value in params.items()}
            for key, value in out_params.items():
                sql = sql.replace(f':{key[1:]}', key)
        elif SQLParams.in_style == 'ordinal':
            out_params = [params[i] for i in range(len(params))]
            sql = re.sub(r'\?', lambda m: f'${m.start() + 1}', sql)
        else:
            raise ValueError(f"Unsupported parameter style: {SQLParams.in_style}")
        return sql, out_params

