import os
import json
import hashlib

class OCFLValidator:
    def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        # Check if the path is a directory
        if not os.path.isdir(path):
            return False

        # Check for required OCFL files
        required_files = ['0=', 'inventory.json']
        for file in required_files:
            if not os.path.exists(os.path.join(path, file)):
                return False

        # Validate the inventory.json
        inventory_path = os.path.join(path, 'inventory.json')
        try:
            with open(inventory_path, 'r') as f:
                inventory = json.load(f)
        except (json.JSONDecodeError, FileNotFoundError):
            return False

        # Check for required keys in inventory
        required_keys = ['id', 'type', 'digestAlgorithm', 'head', 'manifest']
        for key in required_keys:
            if key not in inventory:
                return False

        # Validate each file in the manifest
        for digest, files in inventory['manifest'].items():
            for file_path in files:
                full_path = os.path.join(path, file_path)
                if not os.path.exists(full_path):
                    return False
                if not self._validate_file_digest(full_path, digest, inventory['digestAlgorithm']):
                    return False

        return True

    def _validate_file_digest(self, file_path, expected_digest, algorithm):
        hash_obj = hashlib.new(algorithm)
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_obj.update(chunk)
        return hash_obj.hexdigest() == expected_digest

