class PrettyPrint:
    def __init__(self, data):
        self.data = data

    def pretty(self, indent=0, debug=False):
        def _pretty_print(data, level):
            result = []
            indent_str = '  ' * level
            if isinstance(data, dict):
                result.append("{")
                for key, value in data.items():
                    result.append(f"{indent_str}  {key}: {_pretty_print(value, level + 1)}")
                result.append(f"{indent_str}}}")
            elif isinstance(data, list):
                result.append("[")
                for item in data:
                    result.append(f"{indent_str}  {_pretty_print(item, level + 1)}")
                result.append(f"{indent_str}]")
            else:
                result.append(f"{indent_str}{repr(data)}")
            return ',\n'.join(result)

        if debug:
            print(f"Debugging with indent level {indent}")
        return _pretty_print(self.data, indent)

