from typing import Callable, Any, Dict, List

class HookRegistry:
    def __init__(self):
        self._registry: Dict[str, List[Callable]] = {}

    def on(self, hook: str) -> Callable:
        """Decorator function to add a new handler to the registry.

        Args:
            hook (str): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified hook.
        """
        def decorator(func: Callable) -> Callable:
            if hook not in self._registry:
                self._registry[hook] = []
            self._registry[hook].append(func)
            return func
        return decorator

    def trigger(self, hook: str, *args: Any, **kwargs: Any) -> None:
        """Trigger all handlers registered for a specific hook.

        Args:
            hook (str): The hook to trigger.
            *args: Positional arguments to pass to the handlers.
            **kwargs: Keyword arguments to pass to the handlers.
        """
        if hook in self._registry:
            for func in self._registry[hook]:
                func(*args, **kwargs)

