import hashlib

class VersionValidator:
    def validate_version_inventories(self, version_dirs):
        root_inventory = self.load_inventory(os.path.join(version_dirs[0], 'inventory'))
        content_digests = {}

        for version_dir in version_dirs:
            version_inventory = self.load_inventory(os.path.join(version_dir, 'inventory'))
            self.compare_inventories(root_inventory, version_inventory, version_dir, content_digests)

        return content_digests

    def load_inventory(self, inventory_path):
        with open(inventory_path, 'r') as file:
            inventory = file.readlines()
        return [line.strip() for line in inventory]

    def compare_inventories(self, root_inventory, version_inventory, version_dir, content_digests):
        for item in version_inventory:
            if item not in root_inventory:
                content_path = os.path.join(version_dir, item)
                digest = self.calculate_digest(content_path)
                if digest not in content_digests:
                    content_digests[digest] = []
                content_digests[digest].append(item)

    def calculate_digest(self, file_path):
        hash_md5 = hashlib.md5()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()

