def size_to_bytes(size: str) -> int:
    size_map = {
        'K': 1000,
        'M': 1000**2,
        'G': 1000**3,
        'T': 1000**4,
        'P': 1000**5,
        'E': 1000**6,
        'Z': 1000**7,
        'Y': 1000**8
    }

    if not size:
        return 0

    if size[-1].isalpha():
        multiplier = size_map.get(size[-1].upper(), 1)
        size_number = float(size[:-1])
    else:
