        self._data = data if data is not None else []

    def scale(self, other=None):
        if other is None:
            if self._scale is None or self._scale == 0:
                raise LenaValueError("Graph has unknown or zero scale")
            return self._scale
        else:
            if self._scale is None or self._scale == 0:
                raise LenaValueError("Graph has unknown or zero scale")
            ratio = other / self._scale
            self._scale = other
