from typing import Callable, Tuple, List

class Histogram:
    def __init__(self, bins, scale=None):
        self.bins = bins
        self.scale = scale

class Graph:
    def __init__(self, points, field_names, scale=None):
        self.points = points
        self.field_names = field_names
        self.scale = scale

def hist_to_graph(hist: Histogram, make_value: Callable[[float], Tuple[float, ...]] = None,
                  get_coordinate: str = "left", field_names: Tuple[str, ...] = ("x", "y"),
                  scale: bool = None) -> Graph:
    if make_value is None:
        make_value = lambda bin_: (bin_,)

    points = []
    for bin_ in hist.bins:
        bin_content = bin_[0]
        bin_interval = bin_[1]
        if get_coordinate == "left":
            x = bin_interval[0]
        elif get_coordinate == "right":
            x = bin_interval[1]
        elif get_coordinate == "middle":
            x = (bin_interval[0] + bin_interval[1]) / 2
        else:
            raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

        value = make_value(bin_content)
        point = (x,) + value
        points.append(point)

    graph_scale = hist.scale if scale is True else scale
    return Graph(points, field_names, graph_scale)

