import inspect

class _VerifyErrorCollector:
    def __init__(self):
        self.errors = []

    def add_error(self, error):
        self.errors.append(error)

    def raise_errors(self):
        if len(self.errors) == 1:
            raise self.errors[0]
        elif self.errors:
            raise Invalid("\n".join(str(error) for error in self.errors))

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = _VerifyErrorCollector()

    if not tentative:
        if not iface.providedBy(candidate):
            errors.add_error(Invalid(f"Candidate does not provide the interface {iface.__name__}"))

    required_methods = set(attr for attr in iface.names() if callable(getattr(iface, attr)))
    required_attributes = set(attr for attr in iface.names() if not callable(getattr(iface, attr)))

    candidate_methods = set(name for name, member in inspect.getmembers(candidate, predicate=inspect.ismethod))
    candidate_attributes = set(name for name, member in inspect.getmembers(candidate, predicate=lambda a: not inspect.ismethod(a)))

    missing_methods = required_methods - candidate_methods
    for method in missing_methods:
        errors.add_error(Invalid(f"Missing method: {method}"))

    missing_attributes = required_attributes - candidate_attributes
    for attribute in missing_attributes:
        errors.add_error(Invalid(f"Missing attribute: {attribute}"))

    for method in required_methods.intersection(candidate_methods):
        required_signature = inspect.signature(getattr(iface, method))
        candidate_signature = inspect.signature(getattr(candidate, method))
        if required_signature != candidate_signature:
            errors.add_error(Invalid(f"Method {method} has incorrect signature: expected {required_signature}, got {candidate_signature}"))

    errors.raise_errors()
    return True

