from collections.abc import Callable

def verifyObject(iface, candidate, tentative=False):
    if not tentative and not iface.providedBy(candidate):
        raise Invalid(f"Candidate does not declare that it provides the interface {iface}")

    required_methods = set()
    required_attributes = set()
    for name, attribute in iface.namesAndDescriptions():
        if isinstance(attribute, Callable):
            required_methods.add(name)
        else:
            required_attributes.add(name)

    candidate_methods = set(attr for attr in dir(candidate) if callable(getattr(candidate, attr)))
    candidate_attributes = set(dir(candidate)) - candidate_methods

    missing_methods = required_methods - candidate_methods
    missing_attributes = required_attributes - candidate_attributes

    errors = []

    if missing_methods:
        errors.append(f"Missing methods: {', '.join(missing_methods)}")

    if missing_attributes:
        errors.append(f"Missing attributes: {', '.join(missing_attributes)}")

    for method_name in required_methods:
        if method_name not in missing_methods:
            method = getattr(candidate, method_name)
            iface_method = iface.get(method_name)
            if inspect.signature(method) != inspect.signature(iface_method):
                errors.append(f"Incorrect signature for method {method_name}: {inspect.signature(method)} != {inspect.signature(iface_method)}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
