from collections import Counter, OrderedDict

classLFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = OrderedDict()
        self.freq_counter = Counter()
        self.min_freq = 0

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        freq = self.freq_counter[key]
        self.freq_counter[key] += 1
        self.cache.move_to_end(key)
        self._update_min_freq(freq)
        return self.cache[key]

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self.cache:
            self.cache[key] = value
            self.get(key)
            return
        if len(self.cache) == self.capacity:
            self._evict()
        self.cache[key] = value
        self.freq_counter[key] = 1
        self.min_freq = 1

    def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""
        for key in self.cache:
            if self.freq_counter[key] == self.min_freq:
                del self.cache[key]
                del self.freq_counter[key]
                return key, self.cache.popitem(last=False)[1]
        return None, None

    def _evict(self):
        for key in self.cache:
            if self.freq_counter[key] == self.min_freq:
                del self.cache[key]
                del self.freq_counter[key]
                break
        self._recompute_min_freq()

    def _update_min_freq(self, freq: int):
        if self.min_freq == freq and freq not in self.freq_counter.values():
            self.min_freq += 1

    def _recompute_min_freq(self):
        if not self.cache:
            self.min_freq = 0
        else:
            self.min_freq = min(self.freq_counter.values())

