class TimezoneConverter:
    def __init__(self, target_timezone):
        self.target_timezone = target_timezone

    def _validate_fromutc_inputs(self, method):
        def wrapper(dt):
            if not isinstance(dt, datetime):
                raise TypeError("Input must be an instance of datetime")
            if dt.tzinfo is None:
                raise ValueError("Input datetime must be timezone-aware")
            return method(self, dt)
        return wrapper

    @_validate_fromutc_inputs
    def fromutc(self, dt):
        dt = dt.astimezone(self.target_timezone)
        fold = 0 if dt.utcoffset() == self.target_timezone.utcoffset(dt.replace(fold=0)) else 1
        return dt.replace(fold=fold)

