import requests
from xml.etree import ElementTree as ET

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    base_url = "https://diaspora-the-federation.rhcloud.com/hu"
    webfinger_url = f"{base_url}/webfinger?q={handle}"

    response = requests.get(webfinger_url)
    if response.status_code != 200:
        return {"error": "Failed to retrieve webfinger document"}

    try:
        root = ET.fromstring(response.content)
        parsed_data = {
            "subject": root.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject").text,
            "aliases": [alias.text for alias in root.findall("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Alias")],
            "links": [
                {
                    "rel": link.get("rel"),
                    "href": link.get("href"),
                    "template": link.get("template")
                }
                for link in root.findall("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link")
            ]
        }
        return parsed_data
    except ET.ParseError:
        return {"error": "Failed to parse webfinger document"}

